margin_0_padding_0_box_sizing_border_box:
*{margin:0;padding:0;box-sizing:border-box}
body{font-family:Inter,sans-serif;background:#06060c;color:#eeeef2}
::-webkit-scrollbar{width:4px}::-webkit-scrollbar-thumb{background:#e8a03044;border-radius:2px}
.nav{position:sticky;top:0;z-index:100;background:rgba(6,6,12,.92);backdrop-filter:blur(16px);border-bottom:1px solid rgba(255,255,255,.04);height:60px;display:flex;align-items:center}
.ni{max-width:1100px;margin:0 auto;padding:0 20px;width:100%;display:flex;align-items:center;justify-content:space-between}
.nav-links{display:flex;gap:16px;align-items:center}
.nav-links a{font-size:12px;color:rgba(255,255,255,.4);text-decoration:none}
.nav-links a:hover{color:#fff}
.bp{display:inline-flex;align-items:center;gap:6px;padding:10px 22px;background:#e8a030;color:#fff;border:none;border-radius:8px;font-size:12px;font-weight:600;cursor:pointer;text-decoration:none}
.bp:hover{filter:brightness(1.12);transform:translateY(-2px)}
.hero{min-height:70vh;display:flex;align-items:center;padding:40px 20px}
.hi{max-width:900px;margin:0 auto;text-align:center}
.hero h1{font-family:Space Grotesk,sans-serif;font-size:44px;font-weight:700;line-height:1.1;margin-bottom:14px}
.ac{color:#e8a030}
.sg{max-width:1100px;margin:0 auto;padding:60px 20px;width:100%}
.cg{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}
.card{background:#121220;border:1px solid rgba(255,255,255,.04);border-radius:12px;padding:24px;text-align:center;transition:all .3s;text-decoration:none;color:inherit;display:block}
.card:hover{transform:translateY(-4px);border-color:#e8a03033}
.wf{position:fixed;bottom:20px;right:20px;z-index:99;width:54px;height:54px;border-radius:50%;background:#25D366;display:flex;align-items:center;justify-content:center;box-shadow:0 4px 20px rgba(37,211,102,.3);text-decoration:none;color:#fff;font-size:22px}
.wf:hover{transform:scale(1.1)}
.fu{opacity:0;transform:translateY(20px);transition:all .6s ease-out}
.fu.vis{opacity:1;transform:translateY(0)}
@media(max-width:768px){.cg{grid-template-columns:1fr}}
